package run.ikaros.password; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class PasswordImportService{private final PasswordVaultRepository vaults;private final PasswordVaultItemRepository items;public PasswordImportService(PasswordVaultRepository v,PasswordVaultItemRepository i){vaults=v;items=i;}public Mono<PasswordImportResult> importVault(UUID a,UUID vaultId,EncryptedVaultExport export){return vaults.findById(vaultId).filter(v->v.ownerId().equals(a)&&v.securityProfile().equals(export.securityProfile())).switchIfEmpty(Mono.error(new NotFoundException("Password Vault 不存在、无权访问或安全配置不匹配"))).flatMap(v->{if(v.status()!=PasswordVaultStatus.UNLOCKED)return Mono.error(new ConflictException("Password Vault 尚未解锁"));return reactor.core.publisher.Flux.fromIterable(export.items()).flatMap(item->items.findById(item.id()).flatMap(old->{if(!old.vaultId().equals(vaultId)||old.revision()>item.revision())return Mono.just(false);return items.save(new PasswordVaultItemEntity(item.id(),vaultId,a,item.itemType(),item.encryptedName(),item.encryptedPayload(),item.encryptedCustomFields(),item.favorite(),item.revision(),item.tombstone(),item.createdAt(),Instant.now(),old.version())).thenReturn(true);}).switchIfEmpty(Mono.defer(()->items.save(new PasswordVaultItemEntity(item.id(),vaultId,a,item.itemType(),item.encryptedName(),item.encryptedPayload(),item.encryptedCustomFields(),item.favorite(),item.revision(),item.tombstone(),item.createdAt(),Instant.now(),null)).thenReturn(true))),1).collectList().map(xs->{int ok=0;for(Boolean x:xs)if(x)ok++;return new PasswordImportResult(ok,xs.size()-ok);});});}}
